package com.bank.wherehaving;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

public class SpendReportDao {
    private static final Logger log = Logger.getLogger(SpendReportDao.class.getName());
    private final Connection conn;

    public SpendReportDao(Connection conn) { this.conn = conn; }

    // High spenders: WHERE thins rows, HAVING keeps only big totals.
    public Map<String, BigDecimal> highSpenders(BigDecimal threshold) throws Exception {
        String sql =
            "SELECT account_id, SUM(amount) AS total_spend " +
            "FROM transactions " +
            "WHERE status = 'SUCCESS' AND txn_date >= DATE '2026-01-01' " + // row filter
            "GROUP BY account_id " +
            "HAVING SUM(amount) > ? " +                                      // group filter
            "ORDER BY total_spend DESC";
        Map<String, BigDecimal> out = new LinkedHashMap<>();
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setBigDecimal(1, threshold);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    out.put(rs.getString("account_id"), rs.getBigDecimal("total_spend"));
                }
            }
        }
        log.info(() -> "High spenders above Rs." + threshold + ": " + out);
        return out;
    }
}
