package com.bank.wherehaving;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class ReportDemo {
    private static final Logger log = Logger.getLogger(ReportDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            SpendReportDao dao = new SpendReportDao(conn);

            // Only SAV2001 qualifies: 600000 + 500000 = 1,100,000 > 1,000,000.
            // CUR3001's 350,000 is below the threshold → removed by HAVING.
            // The FAILED 300,000 for SAV2001 never counted → removed by WHERE.
            dao.highSpenders(new BigDecimal("1000000"));

            log.info("WHERE removed FAILED rows; HAVING removed low-total groups.");
        }
    }
}
